from __future__ import annotations

from dataclasses import dataclass, field

from dofutils.maps import CoordinateCell, DefaultMapDataSerializer
from dofutils.value import Dimension

MAP_DATA = ""


@dataclass(frozen=True)
class TestMap:
    data: str = MAP_DATA
    dimensions: Dimension = field(default_factory=lambda: Dimension(15, 17))

    def __post_init__(self):
        object.__setattr__(self, "cells", DefaultMapDataSerializer().deserialize(self.data))
        object.__setattr__(self, "size", len(self.cells))

    def get_cell(self, id: int) -> CoordinateCell:
        data = self.cells[id]
        return CoordinateCell(self, id, data.active and data.movement.walkable(), not data.line_of_sight)
